    dr,dc=deltas[k]
    end=(r+dr,c+dc)
    path=[]
    # Paths observed are horizontal first then vertical for 1; cardinal directions for 2/3.
    if k=='1':
        path=[(r,c+i) for i in range(1,dc+1)] + [(r+dr,c+dc)]
    elif dr:
        path=[(r+i,c) for i in range(1,dr)]
    else:
        step=1 if dc>0 else -1
        path=[(r,c+i) for i in range(step,dc,step)]
    print(k, 'endpoint', end, '5-path', path)

